(7117706, 1087413, 39429, '<td valign="top">A beautiful, vivid shot, but doesn''t share the details of the door and windows.  It is also over sharpened.</td>', 'A beautiful, vivid shot, but doesn''t share the details of the door and windows.  It is also over sharpened.', '2013-10-18 01:09:30.000000', NULL, 1),
(7117707, 1087552, 39429, '<td valign="top">An interesting shot with fascinating movement, however it does not show the details of the door, etc. as given in the challenge.</td>', 'An interesting shot with fascinating movement, however it does not show the details of the door, etc. as given in the challenge.', '2013-10-18 01:10:42.000000', NULL, 1),
(7117711, 1087421, 39429, '<td valign="top">Interesting angle and shot, but missing the "detail in the ordinary." 5</td>', 'Interesting angle and shot, but missing the "detail in the ordinary." 5', '2013-10-18 01:12:35.000000', NULL, 1),
(7117716, 1087401, 39429, '<td valign="top">A fascinating image with some strong emotion, but for me it fails to show the "detail of the ordinary" asked for in the challenge. 5</td>', 'A fascinating image with some strong emotion, but for me it fails to show the "detail of the ordinary" asked for in the challenge. 5', '2013-10-18 01:16:22.000000', NULL, 1),
(7117717, 1087551, 128323, '<td valign="top">Like the title, hope this does well Warren!</td>', 'Like the title, hope this does well Warren!', '2013-10-18 01:16:31.000000', NULL, 1),
(7117719, 1087136, 39429, '<td valign="top">The window itself is wonderful, but the background takes away from the shot for me.  I would have loved to see more light on the front of the window and a dof that would blur out the background.  5</td>', 'The window itself is wonderful, but the background takes away from the shot for me.  I would have loved to see more light on the front of the window and a dof that would blur out the background.  5', '2013-10-18 01:17:59.000000', NULL, 1),
(7117722, 1087283, 39429, '<td valign="top">It is a beautiful pull.  It appears your camera was not parallel to the pull as the top of the picture is in better focus than the bottom.  4</td>', 'It is a beautiful pull.  It appears your camera was not parallel to the pull as the top of the picture is in better focus than the bottom.  4', '2013-10-18 01:19:26.000000', NULL, 1),
(7117726, 1087073, 39429, '<td valign="top">Strange, but interesting.  I love the texture of the iris, but the whole image only works somewhat. 6</td>', 'Strange, but interesting.  I love the texture of the iris, but the whole image only works somewhat. 6', '2013-10-18 01:21:27.000000', NULL, 1),
(7117728, 1087307, 39429, '<td valign="top">I want to like the image, but find the lock lacking in the "detail of the ordinary" called for in the challenge and the moiré distracting. 4</td>', 'I want to like the image, but find the lock lacking in the "detail of the ordinary" called for in the challenge and the moiré distracting. 4', '2013-10-18 01:23:12.000000', NULL, 1),
(7117731, 1087504, 39429, '<td valign="top">This is a beautiful image with wonderful light on the girls.  I may be missing it, but the doors, etc. are not playing a big enough part of the image to meet the challenge for me.  4</td>', 'This is a beautiful image with wonderful light on the girls.  I may be missing it, but the doors, etc. are not playing a big enough part of the image to meet the challenge for me.  4', '2013-10-18 01:25:00.000000', NULL, 1),
