(7117742, 1087422, 39429, '<td valign="top">I love the top 3/4 of the shot.  I would like to have seen the "crop"  exclude the chain link fence and pipe on the right.  6</td>', 'I love the top 3/4 of the shot.  I would like to have seen the "crop"  exclude the chain link fence and pipe on the right.  6', '2013-10-18 01:28:08.000000', NULL, 1),
(7117744, 1087512, 128323, '<td valign="top">That tree was hungry!</td>', 'That tree was hungry!', '2013-10-18 01:29:29.000000', NULL, 1),
