(7117753, 1087556, 39429, '<td valign="top">Interesting doors.  A different time of day and lighting, plus a tighter crop would make a far more interesting image. 5</td>', 'Interesting doors.  A different time of day and lighting, plus a tighter crop would make a far more interesting image. 5', '2013-10-18 01:31:19.000000', NULL, 1),
(7117754, 1087289, 128323, '<td valign="top">Creepy, great use of lighting!  I''d love to know how his face was lit!  Truly amazing considering that the lamp, face light, and back light are all pretty much evenly lit in minimal editing!</td>', 'Creepy, great use of lighting!  I''d love to know how his face was lit!  Truly amazing considering that the lamp, face light, and back light are all pretty much evenly lit in minimal editing!', '2013-10-18 01:31:56.000000', NULL, 1),
