(7121169, 1087315, 170018, '<td valign="top">I wish she is further from the door, so that we don''t see her calm face, contrasting with hands and title! Love the idea though...</td>', 'I wish she is further from the door, so that we don''t see her calm face, contrasting with hands and title! Love the idea though...', '2013-10-24 01:22:11.000000', NULL, 1),
(7121170, 1087486, 170018, '<td valign="top">10! Subject, composition, color, title, even "No trespassing:" sign...</td>', '10! Subject, composition, color, title, even "No trespassing:" sign...', '2013-10-24 01:34:56.000000', NULL, 1),
(7121173, 1087377, 170018, '<td valign="top">That''s the second (and last) 10 I give (why are those ruins so compelling?  :-)). Perfect composition, really! And low light is very attractive.</td>', 'That''s the second (and last) 10 I give (why are those ruins so compelling?  :-)). Perfect composition, really! And low light is very attractive.', '2013-10-24 01:41:10.000000', NULL, 1),
